using System;
using System.Security.Cryptography;
namespace ClinicQueueSystem.Services { public static class PasswordService { public static string Hash(string password) { using (var rng = RandomNumberGenerator.Create()) { byte[] salt = new byte[16]; rng.GetBytes(salt); using (var pbkdf = new Rfc2898DeriveBytes(password, salt, 100000)) { byte[] hash = pbkdf.GetBytes(32); return Convert.ToBase64String(salt) + ":" + Convert.ToBase64String(hash); } } } public static bool Verify(string password, string stored) { try { var p = stored.Split(':'); byte[] salt = Convert.FromBase64String(p[0]); byte[] expected = Convert.FromBase64String(p[1]); using (var pbkdf = new Rfc2898DeriveBytes(password, salt, 100000)) { byte[] actual = pbkdf.GetBytes(32); int diff = actual.Length ^ expected.Length; for (int i = 0; i < actual.Length && i < expected.Length; i++) diff |= actual[i] ^ expected[i]; return diff == 0; } } catch { return false; } } } }